<script setup lang="ts">import{ref,watch}from"vue";const props=defineProps<{open:boolean;provider:string;title:string;deleting?:boolean}>();const emit=defineEmits<{close:[];confirm:[]}>();const confirmation=ref("");watch(()=>props.open,()=>confirmation.value="");</script>
<template><div v-if="open" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel" role="dialog" aria-modal="true" aria-labelledby="vod-delete-title"><h2 id="vod-delete-title">Eliminar disponibilidade</h2><p>Esta ação elimina definitivamente a oferta de <strong>{{provider}}</strong> para <strong>{{title}}</strong>.</p><label class="form-field"><span>Escreve o nome do provider para confirmar</span><input v-model="confirmation" autocomplete="off"></label><div class="form-actions"><button class="button button-secondary" @click="emit('close')">Cancelar</button><button class="button button-danger" :disabled="confirmation!==provider||deleting" @click="emit('confirm')">{{deleting?'A eliminar…':'Eliminar definitivamente'}}</button></div></section></div></template>
